/bin/zsh -lc "node --input-type=module <<'NODE'
import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
const checkpoint = JSON.parse(fs.readFileSync('checkpoint.json', 'utf8'));
assert.equal(checkpoint.current_result.exit_code, 1);
assert.equal(checkpoint.current_result.browser_inspection_completed, false);
assert.equal(checkpoint.next_action, 'verify');
assert.equal(checkpoint.next_step.executed, false);
assert.equal(checkpoint.stopped_before_interaction, true);
for (const [file, digest] of Object.entries(checkpoint.evidence.source_sha256)) {
  assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'), digest, file);
}
for (const file of checkpoint.evidence.missing_artifacts) assert.equal(fs.existsSync(file), false, file);
console.log('checkpoint.json 可解析，失败状态与下一步一致；已记录源文件摘要一致；无浏览器证据产物。此检查不构成 UI 验证通过。');
NODE"

